contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(string calldata description, address caller) public payable {
        require(caller != address(this), "caller must not be the test contract");
        require(caller != address(c), "caller must not be the target contract");
        require(!c.isAdmin(caller), "caller must not be an admin");

        bool reverted;
        try c.newEmergencyOracle(description) {
            reverted = false;
        } catch {
            reverted = true;
        }

        assert(reverted);
    }

    receive() external payable {}
}
